def transform(grid):
    flat=Counter(v for row in grid for v in row)
    interior,lattice=flat.most_common(2)[0][0],flat.most_common(2)[1][0]
    bgn={interior,lattice}
    rows=sorted({i for i,row in enumerate(grid) for v in row if v not in bgn})
    cols=sorted({j for row in grid for j,v in enumerate(row) if v not in bgn})
    out=[]
    for i in range(len(rows)-1):
        row=[]
        for j in range(len(cols)-1):
            cs={grid[r][c] for r in (rows[i],rows[i+1]) for c in (cols[j],cols[j+1])}
            row.append(cs.pop() if len(cs)==1 and not (cs & bgn) else interior)
        out.append(row)
    return out

